script:
setTimeout(function() {
    let parent = (typeof root_element !== 'undefined') ? root_element : document;

    const palette = {
        lightBlue: '#B2D7F7',
        pink: '#F78DA7',
        vividBlue: '#2585E5',
        green: '#41C26A',
        slate: '#A0B2C6',
        coral: '#FA7070',
        purple: '#9B51E0',
        dangerRed: '#F04438'
    };

    function getDateRange(filterType) {
        let now = new Date();
        let formatDate = (d) => {
            let year = d.getFullYear();
            let month = String(d.getMonth() + 1).padStart(2, '0');
            let day = String(d.getDate()).padStart(2, '0');
            return `${year}-${month}-${day}`;
        };

        if (filterType === 'today') {
            let t = formatDate(now);
            return [t, t];
        } else if (filterType === 'this_week') {
            let first = now.getDate() - now.getDay();
            let firstDay = new Date(now.setDate(first));
            let lastDay = new Date();
            return [formatDate(firstDay), formatDate(lastDay)];
        } else if (filterType === 'this_month') {
            let firstDay = new Date(now.getFullYear(), now.getMonth(), 1);
            let lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);
            return [formatDate(firstDay), formatDate(lastDay)];
        } else if (filterType === 'this_year') {
            let firstDay = new Date(now.getFullYear(), 0, 1);
            let lastDay = new Date(now.getFullYear(), 11, 31);
            return [formatDate(firstDay), formatDate(lastDay)];
        }
        return null;
    }

    function renderLegend(container, data, fieldName, dateRange) {
        if (!container) return;
        container.innerHTML = '';
        data.forEach(item => {
            let el = document.createElement('div');
            el.style.cssText = 'display: flex; align-items: flex-start; gap: 10px; cursor: pointer; user-select: none; transition: opacity 0.2s;';
            el.innerHTML = `
                <div style="width: 12px; height: 12px; border-radius: 3px; background: ${item.color}; margin-top: 4px; flex-shrink: 0;"></div>
                <div>
                    <div style="font-size: 14px; font-weight: 600; color: #101828; line-height: 1.2;">${item.label}</div>
                    <div style="font-size: 13px; color: #667085; margin-top: 3px;">${item.value}</div>
                </div>
            `;
            el.addEventListener('mouseenter', () => el.style.opacity = '0.7');
            el.addEventListener('mouseleave', () => el.style.opacity = '1');
            el.addEventListener('click', () => {
                let filterObj = {};
                filterObj[fieldName] = item.label;
                if (dateRange) {
                    filterObj['creation'] = ['between', [`${dateRange[0]} 00:00:00`, `${dateRange[1]} 23:59:59`]];
                }
                frappe.route_options = filterObj;
                frappe.set_route('List', 'HD Ticket');
            });
            container.appendChild(el);
        });
    }

    function parseAgentName(assignData) {
        if (!assignData) return 'Unassigned';
        try {
            let assignedList = typeof assignData === 'string' ? JSON.parse(assignData) : assignData;
            if (Array.isArray(assignedList) && assignedList.length > 0) {
                let email = assignedList[0];
                let key = email.split('@')[0];
                return key.charAt(0).toUpperCase() + key.slice(1);
            }
        } catch (e) {}
        return 'Unassigned';
    }

    function updateDashboard() {
        let selectEl = parent.querySelector('#support-date-filter');
        let filterType = selectEl ? selectEl.value : 'this_month';
        let dateRange = getDateRange(filterType);

        let queryFilters = [];
        if (dateRange) {
            queryFilters.push(["creation", "between", [`${dateRange[0]} 00:00:00`, `${dateRange[1]} 23:59:59`]]);
        }

        // --- Fetch KPI Cards ---
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "HD Ticket",
                fields: ["name", "status", "_assign", "agreement_status", "custom_time_to_accept_sec", "first_response_time", "feedback_rating"],
                filters: queryFilters,
                limit_page_length: 1000
            },
            callback: function(r) {
                let tickets = r.message || [];
                let totalTickets = tickets.length;
                let unassignedCount = 0;
                let slaBreachedCount = 0;
                let totalResponseSec = 0;
                let responseCount = 0;
                let totalRating = 0;
                let ratingCount = 0;

                tickets.forEach(t => {
                    let isClosed = ["Closed", "Resolved"].includes(t.status);
                    let hasAssignee = false;
                    if (t._assign) {
                        try {
                            let parsed = typeof t._assign === 'string' ? JSON.parse(t._assign) : t._assign;
                            if (Array.isArray(parsed) && parsed.length > 0) hasAssignee = true;
                        } catch(e){}
                    }
                    if (!isClosed && !hasAssignee) unassignedCount++;

                    if (t.agreement_status && (t.agreement_status.includes("Failed") || t.agreement_status.includes("Breached"))) {
                        slaBreachedCount++;
                    }

                    let respSec = t.custom_time_to_accept_sec || t.first_response_time;
                    if (respSec && !isNaN(respSec) && respSec > 0) {
                        totalResponseSec += parseFloat(respSec);
                        responseCount++;
                    }

                    if (t.feedback_rating && !isNaN(t.feedback_rating) && t.feedback_rating > 0) {
                        totalRating += parseFloat(t.feedback_rating);
                        ratingCount++;
                    }
                });

                // Format Avg Response Time
                let avgRespStr = "N/A";
                if (responseCount > 0) {
                    let avgSec = Math.round(totalResponseSec / responseCount);
                    if (avgSec < 60) avgRespStr = `${avgSec}s`;
                    else if (avgSec < 3600) avgRespStr = `${Math.round(avgSec / 60)}m`;
                    else avgRespStr = `${(avgSec / 3600).toFixed(1)}h`;
                }

                // Format Rating
                let ratingStr = "N/A";
                if (ratingCount > 0) {
                    let avgRating = (totalRating / ratingCount).toFixed(1);
                    ratingStr = `${avgRating} / 5 ⭐`;
                }

                // Calculate SLA Compliance Rate (%)
                let complianceRate = totalTickets > 0 ? (((totalTickets - slaBreachedCount) / totalTickets) * 100).toFixed(1) : "100";
                let complianceStr = `${complianceRate}%`;

                // Update UI elements
                let unassignedEl = parent.querySelector('#kpi-unassigned');
                let slaEl = parent.querySelector('#kpi-sla-breached');
                let complianceEl = parent.querySelector('#kpi-sla-compliance');
                let respEl = parent.querySelector('#kpi-avg-response');
                let csatEl = parent.querySelector('#kpi-csat');

                if (unassignedEl) unassignedEl.innerText = unassignedCount;
                if (slaEl) slaEl.innerText = slaBreachedCount;
                if (respEl) respEl.innerText = avgRespStr;
                if (csatEl) csatEl.innerText = ratingStr;
                
                if (complianceEl) {
                    complianceEl.innerText = complianceStr;
                    complianceEl.style.color = complianceRate >= 90 ? '#12b76a' : (complianceRate >= 75 ? '#f79009' : '#f04438');
                }
            }
        });

        // 1. Tickets by Status
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "HD Ticket",
                fields: ["status", {"COUNT": "*", "as": "count"}],
                filters: queryFilters,
                group_by: "status",
                order_by: "count desc"
            },
            callback: function(r) {
                let statusChartDiv = parent.querySelector('#tickets-status-chart');
                let statusLegendDiv = parent.querySelector('#tickets-status-legend');
                if (!statusChartDiv) return;

                statusChartDiv.innerHTML = '';
                if (statusLegendDiv) statusLegendDiv.innerHTML = '';

                let rows = r.message || [];
                if (rows.length === 0) {
                    statusChartDiv.innerHTML = '<div style="display:flex; justify-content:center; align-items:center; height:100%; color:#98a2b3; font-size:13px;">No tickets found</div>';
                    return;
                }

                let colorMap = [palette.lightBlue, palette.pink, palette.vividBlue, palette.green, palette.slate];
                let labels = [];
                let values = [];
                let legendItems = [];

                rows.forEach((row, idx) => {
                    let label = row.status || 'Open';
                    let count = row.count || 0;
                    let color = colorMap[idx % colorMap.length];

                    labels.push(label);
                    values.push(count);
                    legendItems.push({ label: label, value: count, color: color });
                });

                new frappe.Chart(statusChartDiv, {
                    type: 'pie',
                    data: { labels: labels, datasets: [{ values: values }] },
                    height: 200,
                    colors: legendItems.map(i => i.color),
                    isNavigable: true,
                    showLegend: false
                });

                renderLegend(statusLegendDiv, legendItems, 'status', dateRange);
            }
        });

        // 2. Tickets by Source
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "HD Ticket",
                fields: ["custom_channel", {"COUNT": "*", "as": "count"}],
                filters: queryFilters,
                group_by: "custom_channel",
                order_by: "count desc"
            },
            callback: function(r) {
                let sourceChartDiv = parent.querySelector('#tickets-source-chart');
                let sourceLegendDiv = parent.querySelector('#tickets-source-legend');
                if (!sourceChartDiv) return;

                sourceChartDiv.innerHTML = '';
                if (sourceLegendDiv) sourceLegendDiv.innerHTML = '';

                let rows = r.message || [];
                if (rows.length === 0) {
                    sourceChartDiv.innerHTML = '<div style="display:flex; justify-content:center; align-items:center; height:100%; color:#98a2b3; font-size:13px;">No tickets found</div>';
                    return;
                }

                let colorMap = [palette.lightBlue, palette.pink, palette.vividBlue, palette.green, palette.slate, palette.coral, palette.purple];
                let labels = [];
                let values = [];
                let legendItems = [];

                rows.forEach((row, idx) => {
                    let label = row.custom_channel || 'Direct';
                    let count = row.count || 0;
                    let color = colorMap[idx % colorMap.length];

                    labels.push(label);
                    values.push(count);
                    legendItems.push({ label: label, value: count, color: color });
                });

                new frappe.Chart(sourceChartDiv, {
                    type: 'donut',
                    data: { labels: labels, datasets: [{ values: values }] },
                    height: 200,
                    colors: legendItems.map(i => i.color),
                    isNavigable: true,
                    showLegend: false
                });

                renderLegend(sourceLegendDiv, legendItems, 'custom_channel', dateRange);
            }
        });

        // 3. Workload by Agent vs SLA Breached by Agent
        let openFilters = [...queryFilters, ["status", "not in", ["Closed", "Resolved"]]];

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "HD Ticket",
                fields: ["name", "agent_group", "_assign", "agreement_status"],
                filters: queryFilters,
                limit_page_length: 1000
            },
            callback: function(r) {
                let agentChartDiv = parent.querySelector('#tickets-agent-chart');
                let slaAgentChartDiv = parent.querySelector('#sla-agent-chart');
                let rows = r.message || [];

                // Workload Chart (Open Tickets)
                if (agentChartDiv) {
                    agentChartDiv.innerHTML = '';
                    let workloadCounts = {};
                    rows.filter(t => !["Closed", "Resolved"].includes(t.status)).forEach(row => {
                        let agent = parseAgentName(row._assign);
                        if (agent === 'Unassigned' && row.agent_group) agent = row.agent_group;
                        workloadCounts[agent] = (workloadCounts[agent] || 0) + 1;
                    });

                    let wLabels = Object.keys(workloadCounts);
                    let wValues = Object.values(workloadCounts);

                    if (wLabels.length > 0) {
                        new frappe.Chart(agentChartDiv, {
                            type: 'bar',
                            data: { labels: wLabels, datasets: [{ name: "Open Tickets", values: wValues }] },
                            height: 200,
                            colors: [palette.vividBlue],
                            isNavigable: true,
                            showLegend: false
                        });
                    } else {
                        agentChartDiv.innerHTML = '<div style="display:flex; justify-content:center; align-items:center; height:100%; color:#98a2b3; font-size:13px;">No open tickets</div>';
                    }
                }

                // SLA Breached by Agent Chart
                if (slaAgentChartDiv) {
                    slaAgentChartDiv.innerHTML = '';
                    let breachCounts = {};
                    rows.filter(t => t.agreement_status && (t.agreement_status.includes("Failed") || t.agreement_status.includes("Breached"))).forEach(row => {
                        let agent = parseAgentName(row._assign);
                        if (agent === 'Unassigned' && row.agent_group) agent = row.agent_group;
                        breachCounts[agent] = (breachCounts[agent] || 0) + 1;
                    });

                    let bLabels = Object.keys(breachCounts);
                    let bValues = Object.values(breachCounts);

                    if (bLabels.length > 0) {
                        new frappe.Chart(slaAgentChartDiv, {
                            type: 'bar',
                            data: { labels: bLabels, datasets: [{ name: "Breached Tickets", values: bValues }] },
                            height: 200,
                            colors: [palette.dangerRed],
                            isNavigable: true,
                            showLegend: false
                        });
                    } else {
                        slaAgentChartDiv.innerHTML = '<div style="display:flex; justify-content:center; align-items:center; height:100%; color:#12b76a; font-size:13px;">No SLA breaches found 🎉</div>';
                    }
                }
            }
        });

        // 4. Actionable Table Widget: Top Breached Tickets
        // التعديل هنا: استخدام مطابقة شاملة للكلمة Failed
        let breachedFilters = [...queryFilters, ["agreement_status", "like", "%Failed%"]];
        
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "HD Ticket",
                fields: ["name", "subject", "priority", "status", "_assign", "creation"],
                filters: breachedFilters,
                order_by: "creation desc",
                limit_page_length: 5
            },
            callback: function(r) {
                let tableContainer = parent.querySelector('#breached-tickets-table-container');
                if (!tableContainer) return;
        
                let tickets = r.message || [];
                if (tickets.length === 0) {
                    tableContainer.innerHTML = '<div style="text-align: center; color: #12b76a; padding: 15px; font-size: 13px; font-weight: 500;">No breached tickets found for this period</div>';
                    return;
                }
        
                let html = `
                    <table style="width: 100%; border-collapse: collapse; font-size: 13px; text-align: left;">
                        <thead>
                            <tr style="border-bottom: 1px solid #eaecf0; color: #667085; background: #f9fafb;">
                                <th style="padding: 8px 12px;">Ticket</th>
                                <th style="padding: 8px 12px;">Subject</th>
                                <th style="padding: 8px 12px;">Assignee</th>
                                <th style="padding: 8px 12px;">Priority</th>
                                <th style="padding: 8px 12px;">Status</th>
                            </tr>
                        </thead>
                        <tbody>
                `;
        
                tickets.forEach(t => {
                    let agent = parseAgentName(t._assign);
                    html += `
                        <tr style="border-bottom: 1px solid #f2f4f7; cursor: pointer;" onclick="frappe.set_route('Form', 'HD Ticket', '${t.name}')">
                            <td style="padding: 10px 12px; font-weight: 600; color: #2585E5;">${t.name}</td>
                            <td style="padding: 10px 12px; color: #101828; max-width: 200px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${t.subject || '-'}</td>
                            <td style="padding: 10px 12px; color: #344054;">${agent}</td>
                            <td style="padding: 10px 12px;"><span style="padding: 2px 8px; border-radius: 4px; font-size: 11px; font-weight: 600; background: #fef3f2; color: #b42318;">${t.priority || 'Medium'}</span></td>
                            <td style="padding: 10px 12px; color: #344054;">${t.status}</td>
                        </tr>
                    `;
                });
        
                html += `</tbody></table>`;
                tableContainer.innerHTML = html;
            }
        });
    }

    // Attach Event Listeners
    let filterSelect = parent.querySelector('#support-date-filter');
    if (filterSelect) filterSelect.addEventListener('change', updateDashboard);

    let btnViewAll = parent.querySelector('#btn-view-all-breached');
    if (btnViewAll) {
        btnViewAll.addEventListener('click', () => {
            frappe.route_options = { "agreement_status": ["like", "%Failed%"] };
            frappe.set_route('List', 'HD Ticket');
        });
    }

    updateDashboard();

}, 1000);
